import assert from 'node:assert/strict';
import { test } from 'node:test';

const optionsForOrdinaryData = { only: true };

test('checks option-shaped data', { only: false }, () => {
  const payload = { only: true };
  assert.equal(payload.only, optionsForOrdinaryData.only);
});

test('checks another payload', () => {
  const payload = { only: true };
  assert.equal(payload.only, true);
});
